const POLICIES = [
    "FIFO",
    "LRU",
    "LFU",
    "NRU",
    "AGING",
    "CLOCK",
    "ECLOCK",
    "WSCLOCK",
    "RANDOM",
    "OPT",
];
const DEFAULTS = [
    "page" => 256,
    "frames" => 4,
    "tlb" => 4,
    "sets" => 1,
    "policy" => "FIFO",
    "scope" => "GLOBAL",
    "asid" => "OFF",
    "tick" => 0,
    "tau" => 8,
    "seed" => 1,
];
class Simulation
{
    public array $c,
        $procs = [],
        $frames = [],
        $tlb = [],
        $swap = [],
        $events = [],
        $history = [];
    public int $time = 0,
        $faults = 0,
        $writebacks = 0,
        $tlbhits = 0,
        $zero = 0,
        $swapin = 0,
        $switches = 0;
    private array $refs;
    private int $cursor = 0,
        $hand = 0,
        $random;
    private ?int $previous = null;
    private bool $fixed = false,
        $trace = false;
    public function __construct(array $config, array $refs)
    {
        $this->c = $config;
        $this->refs = $refs;
        $this->random = $config["seed"];
        $this->frames = array_fill(0, $config["frames"], null);
        $this->tlb = array_fill(0, $config["sets"], []);
    }
function settings(array $w): array
{
    $c = DEFAULTS;
    $seen = [];
    foreach (array_slice($w, 1) as $pair) {
        [$key, $value] = explode("=", $pair);
        if (!array_key_exists($key, $c)) {
            fail("unknown key $key");
        }
        if (isset($seen[$key])) {
            fail("duplicate key $key");
        }
        $seen[$key] = true;
        $n = (int) $value;
        $ranges = [
            "frames" => [1, 16],
            "tlb" => [1, 8],
            "sets" => [1, 8],
            "tick" => [0, 1000],
            "tau" => [1, 1000],
            "seed" => [1, 2147483646],
        ];
        if ($key === "policy") {
            $valid = in_array($value, POLICIES, true);
        } elseif ($key === "scope") {
            $valid = in_array($value, ["GLOBAL", "LOCAL"], true);
        } elseif ($key === "asid") {
            $valid = in_array($value, ["ON", "OFF"], true);
        } elseif ($key === "page") {
            $valid = $n >= 16 && $n <= 4096 && ($n & ($n - 1)) === 0;
        } else {
            $valid = $n >= $ranges[$key][0] && $n <= $ranges[$key][1];
        }
        if (!$valid) {
            fail("invalid $key");
        }
        $c[$key] = in_array($key, ["policy", "scope", "asid"], true) ? $value : $n;
    }
    if ($c["tlb"] % $c["sets"] !== 0) {
        fail("invalid sets");
    }
    return $c;
}
        if ($w[0] === "SYSTEM") {
            $simulation = null;
            $config = settings($w);
            $simulation = new Simulation($config, $refs);
            $parts = ["SYSTEM"];
            foreach ($config as $key => $value) {
                $parts[] = "$key=$value";
            }
            out(implode(" ", $parts));
